$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$routeTemplate = Decode ""

$migration83 = Join-Path $root "supabase\migrations\20260812195600_klyx_multi_slot_market_12_83.sql"
$migration96 = Join-Path $root "supabase\migrations\20260812223200_klyx_group_atomic_live_coverage_12_96.sql"
$fallback15 = Join-Path $root "app\api\market\requests\[id]\split-fallback\route.ts"
$targetDir = Join-Path $root "app\api\market\requests\[id]\split-fallback\slot-map"
$targetPath = Join-Path $targetDir "route.ts"

foreach ($path in @($migration83, $migration96, $fallback15)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.16 : fichier requis introuvable : $path"
    }
}

$sql83 = [System.IO.File]::ReadAllText($migration83)
$sql96 = [System.IO.File]::ReadAllText($migration96)
$fallback = [System.IO.File]::ReadAllText($fallback15)

if (-not $sql83.Contains("KLYX_MULTI_SLOT_MARKET_12_83")) {
    throw "13.16 : migration 12.83 introuvable."
}

if (-not $sql96.Contains("KLYX_GROUP_ATOMIC_LIVE_COVERAGE_12_96")) {
    throw "13.16 : migration 12.96 introuvable."
}

if (-not $sql96.Contains("klyx_group_live_coverage_check")) {
    throw "13.16 : RPC live 12.96 introuvable."
}

if (-not $fallback.Contains("KLYX_MULTI_PROVIDER_FALLBACK_API_13_15")) {
    throw "13.16 : KLYX 13.15 introuvable."
}

if (-not $fallback.Contains("KLYX_MULTI_PROVIDER_FALLBACK_FIX_13_15B")) {
    throw "13.16 : correctif KLYX 13.15b introuvable."
}

# ==========================================================
# DETECTION DE LA VRAIE TABLE DES SLOTS DE 12.83
# ==========================================================

$pattern = '(?is)create\s+table(?:\s+if\s+not\s+exists)?\s+(?:public\.)?([a-zA-Z0-9_]+)\s*\((.*?)\);'
$matches = [regex]::Matches($sql83, $pattern)

$slotTable = $null

foreach ($match in $matches) {
    $tableName = $match.Groups[1].Value
    $block = $match.Groups[2].Value

    $hasRequest = $block -match 'market_request_id'
    $hasStart = $block -match 'start_time|requested_start_time|slot_start_time'
    $hasEnd = $block -match 'end_time|requested_end_time|slot_end_time'
    $isCandidateTable = $tableName -match 'candidate|provider_candidate'

    if ($hasRequest -and $hasStart -and $hasEnd -and -not $isCandidateTable) {
        $slotTable = $tableName
        break
    }
}

if (-not $slotTable) {
    throw "13.16 : impossible de detecter automatiquement la table des slots dans 12.83."
}

Write-Host ("Table slots detectee : " + $slotTable)

$route = $routeTemplate.Replace("__SLOT_TABLE__", $slotTable)

if ($route.Contains("__SLOT_TABLE__")) {
    throw "13.16 : placeholder slot table non remplace."
}

New-Item -ItemType Directory -Force -Path $targetDir | Out-Null

if (Test-Path -LiteralPath $targetPath) {
    $existing = [System.IO.File]::ReadAllText($targetPath)

    if ($existing.Contains("KLYX_MULTI_PROVIDER_EXACT_SLOT_MAP_13_16")) {
        Write-Host "KLYX 13.16 deja applique."
        exit 0
    }

    $timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
    Copy-Item -LiteralPath $targetPath -Destination ($targetPath + ".bak-13-16-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($targetPath, $route, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.16 APPLIQUE"
Write-Host "======================================"
Write-Host ("Table slots : " + $slotTable)
Write-Host "Mapping slot -> provider : EXACT"
Write-Host "Disponibilite planning : LIVE"
Write-Host "Conflits bookings : VERIFIES"
Write-Host "RPC 12.96 : CROSS-CHECK"
Write-Host "Divergence de preuve : FAIL CLOSED"
Write-Host "Prestataire unique N/N : PRIORITAIRE"
Write-Host "Fallback multi-provider : CALCULE"
Write-Host "Selection automatique : NON"
Write-Host "Booking automatique : NON"
Write-Host "Paiement automatique : NON"
Write-Host "Migration : AUCUNE"
Write-Host "======================================"
